INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('الكيمياء العضوية هي إحدى فروع علم الكيمياء. ويدرس بنية وخواص وتفاعلات المركبات والمواد العضوية، أي المواد التي تحتوي على عنصر الكربون. وهي تهتم بالتفاعلات والمواد الداخلة في تكوين الكائنات الحية أو الناتجة من كائن حي، ولهذا سميت بالعضوية. الكيمياء العضوية هي العلم المتعلق بوجود الحياة على الأرض وتبحث في المركبات المرتبطة بالحياة والكائنات الحية.
دراسة المواد العضوية تتضمن استخدام المطيافية (مثل رنين مغناطيسي نووي) ومطيافية الكتلة والطرق الفيزيائية والكيميائية الأخرى لتحديد التركيب الكيميائي والصيغة الكيميائية للمركبات العضوية وفهم تفاعلاتها، بل وإضافة مواد يستفيد منها الإنسان، مثل الأدوية والأسمدة والبوليميرات المختلفة المستخدمة أحيانها كعوازل كهربائية أو حرارية أو صوتية. يدخل في تركيب المواد العضوية بصفة أساسية الكربون والنتروجين والهيدروجين والأكسجين. الكربون هو عمودها الفقري حيث أنه رباعي التكافؤ، وقابل لتكوين سلاسل طويلة وحلقات لجزيئات عضوية، مثل جزيئات البروتين المتعددة والبوليمرات المختلفة . دراسة خواص المواد تتضمن الخواص الفيزيائية والكيميائية، وتستخدم طرقًا شبيهة وطرق تقدير التفاعلية الكيميائية، بهدف فهم سلوك المادة العضوية في شكلها النقي (إن وجد)، وفي المحاليل والمزائج والأشكال المصنعة. وتتضمن دراسة التفاعلات العضوية التحقيق في نطاقها باستخدامها في إعداد المركبات الهدف (مثل المنتجات الطبيعية والأدوية والمكثورات وغيرها) عن طريق الاصطناع الكيميائي، فضلا عن دراسة مركزة في تفاعلية الجزيئات العضوية المفردة، سواء في المختبرات وباستخدام الدراسة النظرية (محاكاة باستخدام الحاسوب).
وتتضمن مجموعة المواد الكيميائية المدروسة في الكيمياء العضوية الهيدروكربونات (مركبات تحتوي على الكربون والهيدروجين فقط)، إضافة إلى عدد لا يحصى من المركبات التي تتكون من الكربون أساسًا، ولكنها تحتوي أيضًا على عناصر أخرى، وهي تدخل أساسا في تكوين الكائنات الحية من نبات أو حيوان أو ناتجة منها . مكوناتها تحتوي على الكربون بالإضافة إلى مكونات أساسية من ضمنها:

الأوكسجين والنيتروجين، والكبريت والفسفور (هذه موجودة في العديد من المركبات الكيميائية العضوية في الأحياء) والهالوجينات. يتميز الكربون بأنه رباعي الترابط، مما ييسر بنائه لسلسلات طويلة عضوية، مثل الكربوهيدرات والبروتينات.
وفي العصر الحديث، اتسع النطاق إلى مزيد من العناصر في الجدول الدوري، مع عناصر المجموعات الرئيسية، بما في ذلك:

المجموعة 1 و2 مركبات عضوية فلزية، أي تتضمن الفلزات القلوية (مثل الليثيوم والصوديوم والبوتاسيوم) أو الفلزات القلوية الترابية (مثل المغنسيوم) أو
أشباه الفلزات (مثل البورون والسيليكون) أو معادن أخرى (مثل الألمنيوم والقصدير).
إضافة إلى ذلك، ركزت البحوث الحديثة في الكيمياء العضوية التي تنطوي على مزيد من الكيمياء العضوية الفلزية، بما في ذلك اللانثينيدات، ولكن خاصة:

الفلزات الانتقالية (مثل الزنك والنحاس والبلاديوم والنيكل والكوبالت والتيتانيوم والكروم، الخ).

ولا تنتمي مركبات الكربون المعقدة إلى مجال الكيمياء غير العضوية . فلا تحتوي المواد غير العضوية على روابط كربون-كربون (مثل أول أكسيد الكربون، وثاني أكسيد الكربون، والأحماض والأملاح والكربيدات والمعادن). وهذا بالطبع لا ينفي وجود مركبات عضوية غير معقدة لا تحتوي على روابط كربون-كربون (مثل الميثان ومشتقاته البسيطة).
ونظرًا للخواص الفريدة للمركبات عديدة الكربون فإنه يوجد مدى بالغ الاتساع لاستخدامات المركبات العضوية. فمثلا تدخل المركبات العضوية كمكونات أساسية في عديد من المنتجات مثل الأدوية والمنتجات البتروكيمياوية واللدائن والأطعمة و الطلاء والمتفجرات والأسمدة والمطاط الاصطناعي والبلاستيك والعديد من المنتجات الأخرى. وبالطبع (بعيدًا عن بعض الاستثناءات البسيطة) فإنها أساس كل العمليات الحيوية التي تتم في أجسام الكائنات الحية، بل هي مركبات الكائنات الحية نفسها، فمكوناتها هي مركبات عضوية بالغة التعقيد. كما أن اختلاف أشكال ونشاط المستبدلات في المركبات العضوية يؤدي لوجود وظائف وأشكال مختلفة لهذه المركبات، مثل حفز الإنزيمات في التفاعلات الحيوية في الأنظمة الحية. وهذه التفاعلات بشكل أو بآخر تعد المحور الذي تدور حوله أشكال الحياة.
ونظرا للخواص الفريدة للكربون، فإنه يعتقد أنه يمكن أن يوجد شكل من أشكال الحياة على النجوم الأخرى اعتمادًا على الكربون، وذلك مع أن احتمالية تغيير ذرة الكربون ب سيليكون والذي يقع أسفل الكربون في الجدول الدوري؛ فتكافؤ الكربون : 4، وتكافؤ السيليكون : 4 أو يزيد.
وتعد الكيمياء العضوية أحد أهم فروع علم الكيمياء الحديثة وتدرس كمنهج منفصل في الكثير من الأنظمة التعليمية في أنحاء العالم.


== تصنيف المواد العضوية ==


=== الوصف والتسمية ===
أول من اهتم بتصنيف المركبات إلى مواد عضوية وغير عضوية هو العالم بريزليوس عن طريق نظريتهِ الحيوية، وهي أن المواد العضوية هي التي تتكون داخل الكائنات الحية، ولا يمكن تحضيرها في المعمل.
تختار التسمية على أساس الأعداد اللاتينية لبعض المكونات التي توجد في الجزيء عدة مرات : مونو (أحادي)، دي (ثنائي) : تري (ثلاثي) وهكذا ؛ ثم تتبعها تسميات للأجزاء الأخرى في الجزيء. كما تستخدم الأعداد العربية المعتادة أحيانا لتعريف ركن من حلقة يرتبط به جزيء من نوع آخر، مثلما في فيتامين بي3 (أنظر الشكل).
لا يمكن التقسيم بدون الحصول على وصف كامل للمكونات المفردة للمركب العضوي.
فعلى عكس الكيمياء غير العضوية، والتي يمكن فيها وصف المركب الكيميائي بواسطة الرموز الكيميائية للعناصر الموجودة في المركب وعدد كل منها، فإنه في الكيمياء العضوية يجب معرفة ترتيب هذه الذرات بالنسبة لبعضها البعض أيضا ليكون هناك توصيف كامل للجزيء؛ فهي معقدة التركيب، بمعنى أن عدد من ذرات الكربونات والهيدروجين مثلا يمكنه تكوين عدة جزيئات، كل منها بتشكيلة مختلفة (أي عدة مواد).
وأحد طرق وصف الجزئ هي رسم المعادلة البنائية. ونظرا لتعقيد هذه الطريقة فقد تم تغييرها، وتبسيطها عبر السنين. وآخر هذه التعديلات هو المعادلة الخطية، والتي تضمن السهولة بدون حدوث لبس أو غموض، وهنا يتم تمثيل كل من الكربون والهيدروجين بصورة ضمنية. وعيوب هذه الطريقة أنه لا يمكن وصفها بالكلمات كما يصعب طباعتها، وهذا يمكن التغلب عليه بواسطة تسمية المواد العضوية.

ونظرا لوجود صعوبة ناتجة من وجود عدد كبير ومتعدد من المركبات العضوية، اعتمد الكيميائيون على نظام عالمي موحد لتسمية المركبات العضوية. وقد تم ميلاد هذه التسمية في جينيف عام 1892 بعد عدة لقاءات دولية متعلقة بهذا الموضوع.
وبالوصول إلى حقيقة أن تعقيد المركبات يزيد في فرع الكيمياء الحيوية، قررت منظمة الايوباك إلحاق الاتحاد الدولي للكيمياء البحتة والتطبيقية (الاتحاد الدولي للكيمياء والجزيئات الحيوية) بها، للوصول إلى تسميات للمركبات المختلفة.
وبمرور الوقت وبزيادة تعقيد المركبات كانت هناك محاولات عديدة من الايوباك لتبسيط طرق التسمية. وقد كانت أول هذه التوصيات عام 1951 عندما تم تسمية البنزين الحلقي سيكلوفان. وبعد ذلك كانت هناك توصيات عديدة لتبسيط تسمية المركبات الحلقية الأخرى والتي تحتوى على ذرات غير متجانسة، مثل الفينولات والنفثالين والبيريدين وغيرها.
ولكن في الواقع لا يزال الاسم التقليدي (غالبا ما يكون مشتق من أصل المركب) لكثير من المركبات يستخدم نظرا لتعقيد الاسم المقترح من الايوباك، إلا في حالة الحاجة لوصف دقيق ومحدد لأحد المركبات فإنه يتم الرجوع لاسم الايوباك. أو في حالة أن الاسم المقترح من الايوباك يكون أسهل من الاسم التقليدي للمركب (فمثلا تسمية الايوباك للكحول الإيثيلي هي الإثانول).


=== تصنيف المواد العضوية ===

تصنيفان رئيسيان:

 مواد عضوية أليفاتية: وهي متسلسلات الكربون وهي مستقيمة وليست حلقية.
 مواد عضوية أروماتية: وهي مركبات حلقية وتتكون من حلقة بنزين واحدة على الأقل.
بصفة عامة  تصنف المواد العضوية طبقا لترتيب بنائها الجزيئي ونشابك الذرات الأخرى بالنسبة لذرة الكربون الرئيسية فيها. في حين يفترض أن ذرات الهيدروجين تشغل كل التكافؤات الفارغة لذرات الكربون، إذا لم تكن مشغولة بذرة كربون آخرى أو بذرة عنصر آخر . لهذا يستغنى مثلا عن رسم ذرات الهيدروجين في حلقة مثل البنزين.


=== الهيدروكربونات والمجموعات الفعالة ===
يبدأ التصنيف عادة بالهيدروكربونات: المركبات التي تحتوى على كربون وهيدروجين فقط. والتصنيفات المشتقة منها، شاهد بالأسفل. أما العناصر الأخرى التي تقدم نفسها في تشكيل ذري تسمى مجموعات فعالة والتي لها تأثير حاسم في الخواص الكيميائية والفيزيائية للمركب، وعلى هذا فإن المجموعات التي لها نفس التكون الذري يكون لها خواص متشابهة، والتي يمكن أن تكون الاختلاط مع الماء، الحمضية، القاعدية، النشاطية الكيميائية، المقاومة للتأكسد، أو بعض الخواص الأخرى. كما أن بعض المجموعات الفعالة قد تكون جذورا حرة، مشابهة للموجودة في الكيمياء غير العضوية، وتعرف على أنها تشكل ذري ينتقل خلال التفاعل الكيميائي من مركب لأخر بدون أن تتغير.
وبعض عناصر المجموعات الفعالة (O, S, N, والهالوجينات) يمكن أن تكون بمفردها واسم مجموعة لا يصلح لها، ولكن نظرا لتأثيرها الحاسم في تغيير خواص الهيدروكربونات التي تتواجد فيها، فإنه يتم تقسيمها ضمن المجموعات الفعالة، وتأثير المجموعات الفعالة على الخواص واضح للغاية في الصفات والتقسيم الناتجين بعد استخدامها.
