INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('أمثلة مركبات أليفاتية:
تؤتي القائمة أسفله بالعديد من المركبات الأليفاتية من البسيط إلى المعقد . تتسم المركبات الأليفاتية بمتسلسلاتها (غير حلقية)، وهي مرتبة هنا بحسب عدد ذرات الكربون في الجزيء:

الهيدروكربونات الأليفاتية تنقسم إلى ثلاث مجموعات، السلاسل المتجانسة طبقا لحالة تشبعها: البارافينات (الألكانات) والتي لا يكون فيها أي روابط ثنائية أو ثلاثية؛ والأولفينات (الألكينات) والتي تحتوى على روابط ثنائية، والتي يمكن أن تكون أولفين أحادى يحتوى على رابطة ثنائية واحدة، أو أولفين ثنائي ويحتوى على رابطتين، أو أولفين متعدد ويحتوى على عدة روابط ثنائية. المجموعة الثالثة هي الألكايينات: وهي تحتوي على رابطة ثلاثية على الأقل (مثل 1-بوتاين ). كما توجد تقسيمات أخرى للمركبات الأليفاتية اعتمادا على المجموعات الفعالة الموجودة بها.
كما أن المركبات الأليفاتية يمكن أن ينظر لها عن طريق استقامة أو تفرع السلسلة المكونة للمركب، ودرجة التفرع أيضا لأن هذا يؤثر على خواصها، مثل رقم الأوكتان في صناعة البترول.


==== المركبات الأروماتية والحلقية الأليفاتية ====

يمكن للمركبات الحلقية أن تكون مشبعة أو غير مشبعة. ونظرا لقيمة الزاوية بين الروابط بين ذرات الكربون فإن الشكل الذي يحتوى على 6 ذرات كربون يعتبر أكثر الأشكال الحلقية ثباتا ؛ ولكن ذلك لا يمنع وجود بعض الحلقات التي تحتوى على 5 ذرات كربون . وفيما عدا ذلك يعتبر نادرا الحدوث. وتنقسم الهيدروكربونات الحلقية إلى حلقية أليفاتية، و حلقية أروماتية والتي يطلق عليها أيضا أرينية.
ومن المركبات الحلقية الأليفاتية التي لا تحتوى على روابط ثنائية الألكانات الحلقية (البارفينات الحلقية)، بينما تحتوى الألكينات الحلقية (الأوليفينات الحلقية) على روابط ثنائية. وأصغر عضو في عائلة الألكانات الحلقية هو البروبان الحلقي. كما توجد مجموعة هامة ضمن الحلقات الأليفاتية هي مجموعة التربينات.
والشيء المختلف في الهيدروكربونات الأروماتية هو احتوائها على روابط ثنائية متبادلة أو مترافقة. وأحد أبسط الأمثلة على ذلك هو حلقة البنزين وبناء البنزين تم اقتراحه بواسطة هوكل والذي كان أول من افترض مبدأ عدم التمركز أو الرنين لتوضيح هذا البناء.
وتتغير صفات الهيدروكربونات الحلقية في حالة وجود مجموعات فعالة، ولكن في بعض الحالات يمكن أن تصنف بعض العناصر التي تكون مجموعات فعالة ضمن الحلقة نفسها. ويطلق على المركبات التي تحتوى على عنصري الكربون والهيدروجين فقط في تركيبها بالحلقات المتجانسة، بينما يطلق على التي تحتوى على عناصر أخرى حلقات غير متجانسة وتسمى الذرة المستبدلة مكان ذرة الكربون بذرة غير متجانسة.
عموما فإن الذرة غير المتجانسة تكون ذرة أكسجين، أو نيتروجين، أو كبريت، ولكن غالبا ما تكون نيتروجين، وتتكون الحلقات غير المتجانسة في الكائنات الحية من النيتروجين. ومن الأمثلة الموجودة للحلقات غير المتجانسة صبغة الأنيلين، ومعظم المركبات التي يتم مناقشتها في الكيمياء الحيوية مثل الألكالويد، ومركبات عديدة من الفيتامينات، الأحماض النووية وعديد من المركبات الطبية. ومن هذه المركبات البنائية البيرول، (خماسي الحلقة)، الإندول (سداسي الحلقة).


==== البوليمرات ====

أحد الخواص الهامة للكربون في الكيمياء العضوية أنه يستطيع تكوين مركبات معينة، تستطيع الجزيئات المفردة لهذه المركبات ربط نفسها ببعض، وبالتالي تكوين سلسلة أو شبكة. وتسمى هذه العملية بلمرة وتسمى السلاسل أو الشبكات المتكونة بوليمرات، بينما يطلق على الجزئ المكون لها بالمونومر. وتوجد مجموعتان رئيسيتان لهذه المركبات: المجموعة التي يتم تصنيعها وتسمى البوليمرات الصناعية، والبوليمرات التي توجد بصورة طبيبعة وتسمى بوليمرات حيوية.
وبمجرد الحصول على أول بوليمر بطريقة صناعية: الباكالايت، إتجهت صناعة البوليمرات نحو النمو بصورة كبيرة. ومن البوليمرات العضوية الشائعة الاستخدام بولى إثيلين أو البوليثين، البولى بروبيلين الذي يستخدم في صناعة نوع قوي من البلاستيك، النايلون، التيفلون أو PTFE، البولى إستر، البولى ميثيل ميثا أكريلات (البلاستيك الشفاف)، بولى فينيل كلوريد PVC.
وكل هذه الأنواع عامة ولكن يوجد لكل منها تفرعات كثيرة بخواص فيزيائية مختلفة لاستخدامات مختلفة. وبتغيير ظروف عملية البلمرة يتغير التركيب الكيميائي للبوليمر الناتج وذلك بحدوث تعديلات في طول السلسلة، أو التفرع، أوالترتيبية. وعند البدء بمونومر واحد فإن البوليمر الناتج يكون متجانس. ويمكن استخدام أكثر من مونومر لإنتاج بوليمر مشترك كما يمكن التحكم في درجة اتحاد مكونات البوليمر ببعضها البعض. وتعتمد الخواص الفيزيائية مثل الصلابة، الكثافة، قوة الشد، مقاومة الاحتكاك، مقاومة الحرارة، اللون على التركيب النهائي.
المادة الوحيدة الأخرى التي يمكن أن ينتج منها بوليمرات هي السيليكون. وللسليكونات اختلافات رئيسية عن البوليمرات الناتجة من الكربون، حيث أنه بخلاف الرابطة الأساسية في البوليمرات الكربونية كربون-كربون، ترتبط ذرات السيليكون ترتبط معا بطريقة غير مباشرة عن طريق روابط من الأكسجين.


==== الجزيئات الحيوية ====
الجزيئات الحيوية هي أحد التصنيفات الرئيسية في الكيمياء العضوية. وتمثل عديد من الجزيئات المعقدة الكبيرة أهمية بالغة في الكائنات الحية. وبعضها يحتوى على سلاسل كبيرة من البوليمرات الحيوية. وتنقسم الجزئيات الحيوية لأقسام رئيسية مثل الكربوهيدرات، الأحماض الأمينية، السكريات المتعددة، الليبيدات، الأحماض النووية.


==== أخرى ====
المركبات العضوية التي تحتوى على روابط بين الكربون والنيتروجين، الأكسجين، الهالوجينات ويتم تقسيمهما منفردة. وتوضع المركبات الأخرى في مجموعات رئيسية ضمن الكيمياء العضوية ويتم مناقشتها تحت عناوين مثل: كيمياء كبريت عضوي، كيمياء فلز عضوي، كيمياء فوسفور عضوي، كيمياء سيليكون عضوي.
لقد قام العالم برذليوس بتقسم المواد لعضوية وغير عضوية ووضع نظرية تسمى نظرية القوى الحيوية التي تنص على أن المركبات العضوية تصنع وتختلق داخل جسم الكائن الحى بتاثير قوى حيوية ولا يمكن تحضيرها في المختبرات
