INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('يستخدم ثنائي إيثيل الإيثر في التخدير الطبي.
تميل المركبات العضوية للذوبان في المذيبات العضوية والتي غالبا ما تكون مواد نقية مثل الإيثر أو الإيثانول أو المخاليط مثل المذيبات البارافينية مثل الإيثرات البترولية المختلفة, الروح البيضاء، أو مدى المخاليط الأروماتية النقية التي يتم الحصول عليها من تقطير البترول بالفصل الفيزيائي أو بالتحويل الكيمياء. الذوبانية في المذيبات المختلفة تعتمد على نوع المذيب وعلى المجموعة الفعالة في حالة وجودها. ويتم دراسة المحاليل بواسطة علم الكيمياء الفيزيائية. ومثل الأملاح غير العضوية يمكن للمركبات العضوية أن تكون بلورات. الخواص الفريدة للكربون في المركبات العضوية راجعة لأن تكافؤه لا يجب أن يؤخذ عادة من العناصر الأخرى، وعندما لا يتم، فإنه ينتج عن ذلك حالة تسمى اصطلاحا بعدم التشبع. وفي هذه الحالة نتحدث عن الرابطة ثنائية أو ثلاثية بين ذرتي كربون. ويسمى التبادل الذي يحدث بين الرابطة الأحادية والرابطة الثنائية في سلسلة بترافق الروابط المزدوجة. بينما يمثل البناء الأروماتي حالة خاصة والتي يحدث الترافق فيها في حلقة مقفولة.', 'Wikipedia Arabic - كيمياء عضوية', 'يستخدم ثنائي إيثيل الإيثر في التخدير الطبي.', 'الكيمياء العضوية', '[-0.0629272,-0.0375366,0.0062027,0.0006895,-0.0337524,-0.0126953,-0.0106125,0.0378418,0.0070076,-0.0188599,0.0144501,0.0180664,0.0121384,0.0135117,-0.0021973,-0.0049744,0.0348511,0.0242157,-0.0531311,0.0040436,-0.0087967,0.0221405,-0.0113602,0.0214233,-0.0408020,-0.0153656,0.0163116,-0.0090179,-0.0135117,0.0392761,0.0345764,-0.0119781,0.0175018,-0.0599670,-0.0369873,0.0001788,0.0121765,-0.0005407,0.0224762,0.0504456,0.0368042,-0.0209656,-0.0418396,0.0244904,-0.0252533,0.0181732,-0.0079346,-0.0706787,0.0557556,0.0062065,-0.0103683,0.0191498,0.0289764,0.0069923,-0.0205688,0.0092392,-0.0181274,0.0402222,-0.0020771,-0.0008602,-0.0276947,-0.0157166,0.0441284,0.0062256,-0.0379944,0.0096436,0.0492554,0.0037899,-0.0079803,0.0145798,0.0053329,-0.0257111,-0.0361633,0.0343628,0.0144043,-0.0149384,0.0022469,-0.0205383,-0.0010777,-0.0070915,-0.0046158,-0.0417175,-0.0002944,-0.0160065,0.0520935,-0.0247650,0.0072708,-0.0155258,-0.0181427,-0.0429382,-0.0066261,0.0111008,-0.0018129,-0.0194