INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('كما توجد طرق أخرى في الكيمياء التحليلية.


== التفاعلات العضوية ==
التفاعلات العضوية هي تفاعلات كيميائية تتضمن مركبات عضوية. وبينما يجتاز الهيدروكربون النقي أنواع معينة من التفاعلات، فإن عديد من التفاعلات العضوية تتم بواسطة المجموعات الفعالة. والنظرية العامة لهذه التفاعلات تهتم بالتحليل الدقيق لخواص هذه المجموعات مثل الألفة الإلكترونية للذرات المؤثرة، قوة الرابطة، الإعاقة الفراغية. وهذه المواضيع تحدد الثبات النسبي للوسيط النشط، والذي عادة ما يحدد مباشرة اتجاه التفاعل. ومثال عام لهذا التفاعل هو تفاعل الاستبدال والذي يكتب كالتالي:', 'Wikipedia Arabic - كيمياء عضوية', 'كما توجد طرق أخرى في الكيمياء التحليلية.', 'الكيمياء العضوية', '[-0.0168610,-0.0655518,0.0188293,0.0401306,0.0501404,0.0447388,0.0026302,0.0019007,-0.0012226,0.0100021,0.0319214,-0.0217133,0.0250702,-0.0154190,0.0018415,0.0447083,-0.0127563,0.0421448,0.0187683,0.0083237,0.0268250,-0.0193481,0.0264893,0.0317993,-0.0518494,-0.0617371,-0.0143051,-0.0202637,-0.0221863,0.0016928,0.0595093,-0.0175934,-0.0152969,-0.0314026,-0.0220184,0.0465393,-0.0550537,0.0563049,0.0032024,-0.0081406,-0.0076447,0.0048714,-0.0806274,0.0114517,-0.0007453,0.0009274,-0.0386963,-0.0514221,0.0124588,-0.0153656,-0.0268402,0.0184937,0.0393677,-0.0099869,-0.0015163,0.0478210,-0.0112076,-0.0009899,0.0085144,0.0236816,-0.0295563,0.0217896,0.0324402,0.0507202,-0.0134277,0.0099792,-0.0049744,-0.0280457,-0.0223541,0.0133057,-0.0034065,0.0047150,-0.0252075,0.0637817,0.0081635,0.0114365,-0.0203094,-0.0038681,-0.0009689,-0.0001886,0.0590515,-0.0218048,-0.0037537,-0.0339966,-0.0022240,-0.0315247,-0.0357971,-0.0526733,-0.0633545,-0.0381470,-0.0200958,0.0090179,-0.0365906,-0.0046272,0.0284119,-0.0227814,0.0110397,-0.0525818,-0.0463257,-0.0165253,0.0501099,0.0005484,-0.0243378,0.0132523,0.0469360,-0.0052032,-0.0082169,-0.0531921,-0.0423279,0.0170746,0.0541382,-0.0303040,-0.0224304,-0.0084763,0.0352783,-0.0515137,0.0194092,0.0382996,0.0071754,-0.0160828,0.0134888,0.0039101,0.0910645,0.0097656,0.0276337,-0.0636597,-0.0178986,0.0067558,-0.0315552,-0.0059967,-0.0050850,0.0086060,-0.0358582,0.0209808,-0.0294037,-0.013